-- GENERATED by `wfj generate` from data/gossip/gossip-f7.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f704059f1bf06471"] = { "Osi sfidarmi? Preparati a un'eternità di terrore.", "." },
  ["f707cff6c892b548"] = { "Abbiamo un accordo?", "." },
  ["f70ac63855f70656"] = { "Mmmm, che buono. Ma ora è tempo di tornare al lavoro!", "." },
  ["f712ebe7173a80e5"] = { "Cosa ne sai, Franzahl?", "." },
  ["f716a8d7ba5f49b1"] = { "Il frullo delle ali di un falco, il respiro di un ariete nella neve, il passo di un orso nella foresta... Così è la vita del cacciatore.", "." },
  ["f717fe3f21756d77"] = { "%s poi prende la mira verso le bottiglie...", "." },
  ["f7245a6206447837"] = { "Hai trovato qualche indizio su cos'è successo alla ⟦Shady Rest Inn=Locanda Ombracalma⟧?", "." },
  ["f7271dda0743f646"] = { "Istruttore di classe", "." },
  ["f72ca24580ed7a7b"] = { "Uno stregone, eh... Be', se hai in mente di fare quel genere di cose da queste parti, allora faresti meglio a tenere i tuoi demoni al guinzaglio, <ragazzo/ragazza>. Non mi piacciono i demoni, ma adoro piantarci dentro l'ascia. Mi capisci?\n\nOra lasciami in pace e va' a perderti nella Forlorn Cavern. È lì che troverai quello stregone, Thistleheart.", "." },
  ["f732a20054e433bc"] = { "Il Windfield Orchard ha visto giorni migliori...", "." },
  ["f738008ef33daec7"] = { "Il Flagello ha sfondato in tutte le ali! Che la Luce sconfigga queste immonde creature! Combatteremo fino all'ultimo!", "." },
  ["f73e71f92a2a6f76"] = { "Sei qui per addestrarti? O sei qui solo per far perdere tempo a un guerriero?", "." },
  ["f73f96c116c428e4"] = { "Capitolo sulla ⟦Skin of Shadow=Pelle dell'Ombra⟧.", "." },
  ["f7422ffbb893754b"] = { "Allora ascolta bene, {race}.\n\nAlcuni mesi fa, il magistrato di ⟦Lakeshire=Borgolago⟧ inviò dei messi a ⟦Ironforge=Forgiardente⟧, implorando il re di aiutarli contro le incursioni dei ⟦Blackrock=Roccianera⟧ provenienti da ⟦Redridge=Crestarossa⟧ e dalle ⟦Burning Steppes=Steppe Ardenti⟧.\n\nLa principessa Moira si offrì volontaria per aiutarli, nonostante le mie suppliche. Mi furono assegnate venti guardie scelte per proteggere la principessa durante il pericoloso viaggio dal Loch a ⟦Lakeshire=Borgolago⟧.", "." },
  ["f74635b18b8bbe93"] = { "Ecco fatto, {name}. Meno male che i miei poteri di divinazione ed evocazione funzionano ancora in questo stato spettrale, eh?", "." },
  ["f746bf314924ff11"] = { "Buon acciaio, {name}. Prendi un martello e vieni qui, lascia che ti mostri il segreto per forgiare un'arma leggendaria.", "." },
  ["f74a15f6e945749b"] = { "Andrà tutto bene, vedrai.", "." },
  ["f74e73ea202e7de7"] = { "I Creatori sono... i Creatori.\n\nSono gli esseri che hanno seminato e plasmato questo mondo secondo il proprio disegno. Sono la ragione dell'esistenza di questo mondo, così come di molti altri mondi. Sono la sorgente da cui scaturisce Azeroth.", "." },
  ["f74e7eaf90b1a723"] = { "Salute, {name}. Vedo che risulti già aver completato la missione per ottenere l'accesso a Naxxramas. Assicurati di parlare con il comandante Eligor Dawnbringer alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, per ottenere la missione «Echoes of War». Devi completare prima quella missione per poter accedere alle missioni del tuo set di armatura di Tier 3.\n\nPosso teletrasportarti direttamente a Naxxramas, oppure puoi usare il portale che si trova a ⟦Plaguewood=Malaselva⟧, a ovest.", "." },
  ["f74ed677acddfe1d"] = { "Venite, miei accoliti. Prendete le verghe di incanalamento e create il cerchio d'evocazione superiore.", "." },
  ["f7528a8aa505fb70"] = { "Soldati semplici Marcus, Tremane, Osgood, Lampret...", "." },
  ["f7531c115dcb5b37"] = { "Sei stato lontano troppo a lungo, Malfurion. La pace tra i figli di Azeroth è fragile, nel migliore dei casi. Che ne è di mio padre? Di tuo fratello? Hai notizie?", "." },
  ["f757e909f0cf6a5c"] = { "Fate vedere di che pasta siete fatti! All'attacco!", "." },
  ["f75f946edcc34815"] = { "La città in rovina di Stratholme si trova nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, a nord della ⟦Plaguewood=Malaselva⟧.", "." },
  ["f76380e4795efdef"] = { "Non sapevo che alle api non piacesse il fuoco!", "." },
  ["f7693d23090c8d26"] = { "Credo che avrai più fortuna a cercare a ⟦Stormwind=Roccavento⟧. Chiedi a una guardia lassù e ti indicherà la strada giusta.", "." },
  ["f76dcea552bde8ef"] = { "I segni su questa tavoletta mostrano antichi diagrammi e terribili parole di potere, usati per creare il ⟦Gurubashi Mojo Madness=Mojo della Follia dei Gurubashi⟧...", "." },
  ["f76ecf08e84de635"] = { "Drek'Thar è stato sconfitto! L'⟦Alliance=Alleanza⟧ è vittoriosa... per ora.\n\nParla con il nostro intendente e aiutaci nella ricostruzione.", "." },
  ["f775e33ae623fec9"] = { "%s rivolge la sua attenzione verso di te.", "." },
  ["f77b3724e9f0a5d3"] = { "Accidenti, qui i pesci proprio non abboccano. Forse dovrei andare al ⟦Crystal Lake=Lago di Cristallo⟧ a tentare la fortuna lì!", "." },
  ["f77f1596b7a8412a"] = { "Dovrebbe bastare! Hic!", "." },
  ["f785c2d94840977d"] = { "Con i calderoni violati, ora possiamo introdurre l'agente neutralizzante nell'ambiente. Questo dovrebbe ripagare il Flagello con la sua stessa moneta, per così dire!\n\nRivolgiti all'alchimista Arbington per le informazioni sui reagenti da usare nei calderoni. Io mi occuperò di tutti i rapporti su come stiamo procedendo nel complesso per rivoltare la piaga contro il Flagello!", "." },
  ["f786ac6d6467c128"] = { "Ah, <sacerdote/sacerdotessa>, capiti proprio al momento giusto. Ti ringrazio.", "." },
  ["f7887b878f594b64"] = { "Azshara è sotto attacco in questo momento?", "." },
  ["f79850f4d8fc8e3c"] = { "Ho sete.", "." },
  ["f7a41f7eedd2a6e1"] = { "Ci spiace lasciare un cliente, ma abbiamo posti dove andare e gente da imbrogliare. Torneremo più tardi in giornata. Arrivederci!", "." },
  ["f7a7f9bddc8ef273"] = { "Sei qui per imparare ad accamparti nelle terre selvagge?", "." },
  ["f7abce0bb335533b"] = { "Maestro di guerra", "." },
  ["f7aece84c935c319"] = { "Lo Sciamano al comando non va preso alla leggera, {race}.", "." },
  ["f7b163b25e4fb230"] = { "Ebbene, <ragazzo/ragazza>, pare che l'⟦Alliance=Alleanza⟧ abbia già raccolto tutto ciò che ci serve per la nostra parte della guerra. So che i fabbri, gli ingegneri e tutti gli altri sono impegnati negli ultimi preparativi, e non appena l'⟦Horde=Orda⟧ avrà radunato tutte le sue merci, tutto verrà spedito a ⟦Silithus=Silitus⟧ per la guerra.", "." },
  ["f7b3d8f7fdfcb1af"] = { "Ma sei matt<o/a>? Quella non è un'arma, è un coltello da tavola. Io non addestro i dilettanti.", "." },
  ["f7b5425be514be0f"] = { "Mi fa piacere rivederti, {name}.", "." },
  ["f7b6e1718c0bbd6a"] = { "Ecco, ce l'ho!", "." },
  ["f7c214ba8af19dcb"] = { "Ehi, sento un po' d'incredulità nella tua voce... ma sì, è andata proprio così.", "." },
  ["f7c68f7ff24e0c3e"] = { "Il sangue dei nostri nemici sarà versato sul campo di battaglia. I grandi elementali risponderanno alla nostra chiamata e schiacceranno chiunque ci sbarri la strada.", "." },
  ["f7c7151196ccb45b"] = { "Aiuto! La bestia mi è addosso!", "." },
  ["f7c83a44b7adc2f0"] = { "Incredibile! Conosco colui che ha creato questi incantamenti...", "." },
  ["f7c8d25189d09a3f"] = { "Dai, proviamo da un'altra parte.", "." },
  ["f7d4e53caf0bc67c"] = { "Hai proprio un'abilità notevole, {name}. Le lame e i martelli che fai superano perfino i miei, per quanto mi costi ammetterlo. L'unica persona che abbia mai incontrato con un'abilità ancora maggiore è Borgus Steelhand: scommetto che potrebbe insegnarti una cosa o tre.", "." },
  ["f7dbaf60aab1d2e4"] = { "Non ho più le mie ⟦Zandalar Confessor's Bindings=Manette del Confessore degli Zandalari⟧. Puoi darmene di nuove?", "." },
  ["f7dff2b7b9d3c80c"] = { "Tu, lì... è nel tuo interesse aiutare i Reietti in questi tempi difficili. Ascolta bene, perché detesto ripetermi.\n\nAl momento ci troviamo a corto di stoffa. Bende e tessuti semplici scarseggiano, e accettiamo donazioni per rimpinguare le scorte in calo. Anche se non riceverai un compenso in denaro (è questo che significa donazione), il tuo aiuto non passerà inosservato.", "." },
  ["f7e2251b51cdda24"] = { "Che peccato: a quanto pare abbiamo raccolto tutte le bende di telamagica necessarie. Forse puoi andare a venderle alla casa d'aste? Ma prima di andare, fai <il/la> <bravo/brava> <ragazzo/ragazza> e chiedi agli altri raccoglitori presenti. Potrebbero avere una commissione da affidarti.", "." },
  ["f7efde6eb07f4631"] = { "Dicono che questi fuochi d'artificio usino il potere della luna!", "." },
  ["f7f13fb867905157"] = { "L'anziano Moonwarden sta osservando il ⟦Crossroads=Crocevia⟧ nelle ⟦Barrens=Savane⟧.", "." },
  ["f7f23579348fb3d1"] = { "Eh, bombe, noi piacere bombe. Graham Van Talen fare vedere te come fare. Lui in anello esterno di ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "." },
  ["f7f50691cb6facbf"] = { "Qui rispetterai le nostre regole, canaglia!", "." },
  ["f7f82bf278ac8c1b"] = { "Concedimi la saggezza degli Asciafredda!", "." },
  ["f7fc6db848444ef2"] = { "Lo giustizio come ordinato dal mio signore, ma nel modo meno doloroso possibile. Giustizia va fatta, ma posso mostrare un po' di compassione.", "." },
  ["f7fef512e8e1510e"] = { "Dov'è l'istruttore di Forgiatura?", "." },
})
